    static TagTechnology technology(Tag tag,String name)throws Exception{switch(name){case "NfcA":return NfcA.get(tag);case "NfcB":return NfcB.get(tag);case "NfcF":return NfcF.get(tag);case "NfcV":return NfcV.get(tag);case "IsoDep":return IsoDep.get(tag);case "Ndef":return Ndef.get(tag);case "NdefFormatable":return NdefFormatable.get(tag);case "MifareClassic":return MifareClassic.get(tag);case "MifareUltralight":return MifareUltralight.get(tag);case "NfcBarcode":return NfcBarcode.get(tag);default:throw new VmHardware.Failure("invalid_argument","Use an Android NFC technology name, e.g. IsoDep or Ndef.");}}
